insert into catalog_phases (model_id, generation_code, phase_label, year_from, year_to, display_name, platform_code, safety_rating, ncap_year, ncap_adult_pct, ncap_child_pct, ncap_pedestrian_pct, ncap_safety_assist_pct, avg_market_price_eur, price_range_min_eur, price_range_max_eur, typical_mileage_range, resale_value_rating, towing_capacity_kg)
select m.id, v.generation_code, v.phase_label, v.year_from, v.year_to, v.display_name, v.platform_code,
  v.safety_rating, v.ncap_year, v.ncap_adult_pct, v.ncap_child_pct, v.ncap_pedestrian_pct, v.ncap_safety_assist_pct,
  v.avg_market_price_eur, v.price_range_min_eur, v.price_range_max_eur, v.typical_mileage_range,
  v.resale_value_rating, v.towing_capacity_kg
from (
  values
    ('3H7'::text, 'Pre-facelift'::text, 2017::integer, 2020::integer, 'Arteon (3H7) Pre-facelift'::text, 'MQB'::text, 5::integer, 2017::integer, 96::integer, 85::integer, 85::integer, 82::integer, 25500::integer, 18000::integer, 37000::integer, '80000 - 220000 km'::text, 'holds_well'::text, 2200::integer),
    ('3H7'::text, 'Facelift'::text, 2020::integer, 2024::integer, 'Arteon (3H7) Facelift'::text, 'MQB'::text, 5::integer, 2017::integer, 96::integer, 85::integer, 85::integer, 82::integer, 36000::integer, 26000::integer, 56000::integer, '30000 - 120000 km'::text, 'holds_well'::text, 2200::integer)
) as v(generation_code, phase_label, year_from, year_to, display_name, platform_code,
  safety_rating, ncap_year, ncap_adult_pct, ncap_child_pct, ncap_pedestrian_pct, ncap_safety_assist_pct,
  avg_market_price_eur, price_range_min_eur, price_range_max_eur, typical_mileage_range,
  resale_value_rating, towing_capacity_kg)
join catalog_models m on m.name = 'Arteon'
join catalog_brands cb on cb.id = m.brand_id and cb.name = 'Volkswagen'
where not exists (
  select 1 from catalog_phases cp where cp.model_id = m.id and cp.generation_code = v.generation_code and cp.phase_label = v.phase_label
);

