      ('Facelift'::text, 'Liftback'::text, 'DFEA'::text, 140::integer, 'DQ381'::text, null::text),
      ('Facelift'::text, 'Estate'::text, 'DFEA'::text, 140::integer, 'DQ381'::text, null::text),
